insert into public.student_offers (id, name, provider, category, summary, eligibility, how_to_verify, url, countries, university_ids, status, source_url, last_verified, sort_order) values ('github_student_pack', 'GitHub Student Developer Pack', 'GitHub', 'developer', 'Free access to a bundle of developer tools and services from GitHub and its partners.', 'Enrolled in a degree or diploma program, at least 13 years old, with a personal GitHub account.', 'School email address, or proof of current enrollment such as a student ID or transcript.', 'https://education.github.com/pack', array[]::text[], array[]::text[], 'active', 'https://help.github.com/articles/applying-for-a-student-developer-pack', '2026-10-22', 0) on conflict (id) do update set name = excluded.name, provider = excluded.provider, category = excluded.category, summary = excluded.summary, eligibility = excluded.eligibility, how_to_verify = excluded.how_to_verify, url = excluded.url, countries = excluded.countries, university_ids = excluded.university_ids, status = excluded.status, source_url = excluded.source_url, last_verified = excluded.last_verified, sort_order = excluded.sort_order;
insert into public.student_offers (id, name, provider, category, summary, eligibility, how_to_verify, url, countries, university_ids, status, source_url, last_verified, sort_order) values ('jetbrains_student', 'JetBrains free student license', 'JetBrains', 'developer', 'Free individual licenses for JetBrains tools (such as IntelliJ IDEA and PyCharm), valid one year and renewable while you study.', 'Enrolled at an accredited school, college or university in a program of a year or more of full-time study.', 'School email address, an ISIC card, or a GitHub Student Developer Pack account.', 'https://www.jetbrains.com/student/', array[]::text[], array[]::text[], 'active', 'https://www.jetbrains.com/student/', '2026-10-22', 1) on conflict (id) do update set name = excluded.name, provider = excluded.provider, category = excluded.category, summary = excluded.summary, eligibility = excluded.eligibility, how_to_verify = excluded.how_to_verify, url = excluded.url, countries = excluded.countries, university_ids = excluded.university_ids, status = excluded.status, source_url = excluded.source_url, last_verified = excluded.last_verified, sort_order = excluded.sort_order;
insert into public.student_offers (id, name, provider, category, summary, eligibility, how_to_verify, url, countries, university_ids, status, source_url, last_verified, sort_order) values ('figma_education', 'Figma for Education', 'Figma', 'design', 'Figma''s Education plan, free for verified students (Professional plan for higher education).', 'Students and educators, 13 or older, applying with their school email.', 'Apply at figma.com/education; verification is done by SheerID.', 'https://www.figma.com/education/', array[]::text[], array[]::text[], 'active', 'https://help.figma.com/hc/en-us/articles/360041061214', '2026-10-22', 2) on conflict (id) do update set name = excluded.name, provider = excluded.provider, category = excluded.category, summary = excluded.summary, eligibility = excluded.eligibility, how_to_verify = excluded.how_to_verify, url = excluded.url, countries = excluded.countries, university_ids = excluded.university_ids, status = excluded.status, source_url = excluded.source_url, last_verified = excluded.last_verified, sort_order = excluded.sort_order;
insert into public.student_offers (id, name, provider, category, summary, eligibility, how_to_verify, url, countries, university_ids, status, source_url, last_verified, sort_order) values ('notion_education', 'Notion Plus for students', 'Notion', 'productivity', 'Notion''s Plus plan free for college and university students.', 'Students at an accredited college or university (not K-12).', 'Sign up with your school email, then Settings → Upgrade plan → Get free education plan.', 'https://www.notion.com/product/notion-for-education', array[]::text[], array[]::text[], 'active', 'https://www.notion.com/help/notion-for-education', '2026-10-22', 3) on conflict (id) do update set name = excluded.name, provider = excluded.provider, category = excluded.category, summary = excluded.summary, eligibility = excluded.eligibility, how_to_verify = excluded.how_to_verify, url = excluded.url, countries = excluded.countries, university_ids = excluded.university_ids, status = excluded.status, source_url = excluded.source_url, last_verified = excluded.last_verified, sort_order = excluded.sort_order;
insert into public.student_offers (id, name, provider, category, summary, eligibility, how_to_verify, url, countries, university_ids, status, source_url, last_verified, sort_order) values ('autodesk_education', 'Autodesk Education', 'Autodesk', 'design', 'One year of free access to Autodesk software for learning, renewable while you''re eligible. Not for commercial work.', 'Students and educators at qualified educational institutions.', 'Autodesk checks your student status when you sign up for education access.', 'https://www.autodesk.com/education/edu-software/overview', array[]::text[], array[]::text[], 'active', 'https://www.autodesk.com/education/home', '2026-10-22', 4) on conflict (id) do update set name = excluded.name, provider = excluded.provider, category = excluded.category, summary = excluded.summary, eligibility = excluded.eligibility, how_to_verify = excluded.how_to_verify, url = excluded.url, countries = excluded.countries, university_ids = excluded.university_ids, status = excluded.status, source_url = excluded.source_url, last_verified = excluded.last_verified, sort_order = excluded.sort_order;
insert into public.student_offers (id, name, provider, category, summary, eligibility, how_to_verify, url, countries, university_ids, status, source_url, last_verified, sort_order) values ('microsoft_365_education', 'Microsoft 365 Education', 'Microsoft', 'productivity', 'Free web versions of Word, Excel, PowerPoint, OneNote and Teams for students at eligible schools. What''s included depends on your school''s license.', 'Students at an eligible school or university.', 'Sign up with your school email address.', 'https://www.microsoft.com/en-us/education/products/microsoft-365', array[]::text[], array[]::text[], 'active', 'https://www.microsoft.com/en-us/education/products/microsoft-365', '2026-10-22', 5) on conflict (id) do update set name = excluded.name, provider = excluded.provider, category = excluded.category, summary = excluded.summary, eligibility = excluded.eligibility, how_to_verify = excluded.how_to_verify, url = excluded.url, countries = excluded.countries, university_ids = excluded.university_ids, status = excluded.status, source_url = excluded.source_url, last_verified = excluded.last_verified, sort_order = excluded.sort_order;
insert into public.student_offers (id, name, provider, category, summary, eligibility, how_to_verify, url, countries, university_ids, status, source_url, last_verified, sort_order) values ('uwi_microsoft_365', 'Microsoft 365 through UWI', 'The University of the West Indies', 'productivity', 'UWI gives every St. Augustine student an Office 365 account: email, OneDrive and Office apps such as Word, Excel and PowerPoint.', 'Registered UWI St. Augustine students.', 'Sign in with your UWI student account. Campus IT (sta.uwi.edu/cits) has setup guides.', 'https://uwi.edu/o365/', array[]::text[], array['uwi_st_augustine']::text[], 'active', 'https://uwi.edu/o365/', '2026-10-22', 6) on conflict (id) do update set name = excluded.name, provider = excluded.provider, category = excluded.category, summary = excluded.summary, eligibility = excluded.eligibility, how_to_verify = excluded.how_to_verify, url = excluded.url, countries = excluded.countries, university_ids = excluded.university_ids, status = excluded.status, source_url = excluded.source_url, last_verified = excluded.last_verified, sort_order = excluded.sort_order;
insert into public.student_offers (id, name, provider, category, summary, eligibility, how_to_verify, url, countries, university_ids, status, source_url, last_verified, sort_order) values ('uwi_pelican_perks', 'Pelican Perks', 'UWI Alumni Association', 'shopping', 'Discounts at partner businesses, many in Trinidad and Tobago. Partners and discounts change often.', 'UWI students with a valid UWI student ID.', 'Show your UWI student ID at the partner business.', 'https://uwi.edu/alumnionline/membership/pelican-perks', array[]::text[], array['uwi_st_augustine']::text[], 'active', 'https://uwi.edu/alumnionline/membership/pelican-perks', '2026-10-22', 7) on conflict (id) do update set name = excluded.name, provider = excluded.provider, category = excluded.category, summary = excluded.summary, eligibility = excluded.eligibility, how_to_verify = excluded.how_to_verify, url = excluded.url, countries = excluded.countries, university_ids = excluded.university_ids, status = excluded.status, source_url = excluded.source_url, last_verified = excluded.last_verified, sort_order = excluded.sort_order;
insert into public.student_offers (id, name, provider, category, summary, eligibility, how_to_verify, url, countries, university_ids, status, source_url, last_verified, sort_order) values ('spotify_premium_student_us', 'Spotify Premium Student (with Hulu)', 'Spotify', 'music', 'Discounted Spotify Premium for students; in the US it includes Hulu (With Ads) at no extra cost. Up to 4 years, re-verify every 12 months.', '18 or older and enrolled at a US Title IV accredited college or university.', 'Verified by SheerID — you may log in to your school portal or upload proof of enrollment.', 'https://www.spotify.com/us/student/', array['US']::text[], array[]::text[], 'active', 'https://support.spotify.com/us/account_payment_help/subscription_information/spotify-and-hulu', '2026-10-22', 8) on conflict (id) do update set name = excluded.name, provider = excluded.provider, category = excluded.category, summary = excluded.summary, eligibility = excluded.eligibility, how_to_verify = excluded.how_to_verify, url = excluded.url, countries = excluded.countries, university_ids = excluded.university_ids, status = excluded.status, source_url = excluded.source_url, last_verified = excluded.last_verified, sort_order = excluded.sort_order;
insert into public.student_offers (id, name, provider, category, summary, eligibility, how_to_verify, url, countries, university_ids, status, source_url, last_verified, sort_order) values ('apple_music_student', 'Apple Music student subscription', 'Apple', 'music', 'Discounted Apple Music for students, with Apple TV+ included. Up to 48 months; re-verify once a year.', 'Students at a college or university in a country where the student plan is offered.', 'In Apple Music choose Student → Verify Eligibility; checked by UNiDAYS or SheerID.', 'https://support.apple.com/106008', array['US']::text[], array[]::text[], 'active', 'https://support.apple.com/106008', '2026-10-22', 9) on conflict (id) do update set name = excluded.name, provider = excluded.provider, category = excluded.category, summary = excluded.summary, eligibility = excluded.eligibility, how_to_verify = excluded.how_to_verify, url = excluded.url, countries = excluded.countries, university_ids = excluded.university_ids, status = excluded.status, source_url = excluded.source_url, last_verified = excluded.last_verified, sort_order = excluded.sort_order;
insert into public.student_offers (id, name, provider, category, summary, eligibility, how_to_verify, url, countries, university_ids, status, source_url, last_verified, sort_order) values ('youtube_premium_student', 'YouTube Premium student membership', 'YouTube', 'music', 'Discounted YouTube Premium or YouTube Music Premium for students. Up to 4 years; re-verify every year.', 'Enrolled at a higher-education institution approved by SheerID, in a country where student plans are offered.', 'Pick your school on the SheerID form from YouTube''s student plan page.', 'https://support.google.com/youtube/answer/9158808', array['US']::text[], array[]::text[], 'active', 'https://support.google.com/youtube/answer/9158808', '2026-10-22', 10) on conflict (id) do update set name = excluded.name, provider = excluded.provider, category = excluded.category, summary = excluded.summary, eligibility = excluded.eligibility, how_to_verify = excluded.how_to_verify, url = excluded.url, countries = excluded.countries, university_ids = excluded.university_ids, status = excluded.status, source_url = excluded.source_url, last_verified = excluded.last_verified, sort_order = excluded.sort_order;
