insert into public.student_offers (id, name, provider, category, summary, eligibility, how_to_verify, url, countries, university_ids, status, source_url, last_verified, sort_order) values ('uwi_health_services', 'Campus Health Services', 'UWI St. Augustine Health Services Unit', 'other', 'A walk-in clinic and pharmacy on campus with free screenings and nurse evaluations; full-time registered students have the Student Health Plan.', 'Registered UWI St. Augustine students (the Student Health Plan is for full-time students).', 'Show your valid UWI student ID at the front desk.', 'https://sta.uwi.edu/HEALTH/about', array[]::text[], array['uwi_st_augustine']::text[], 'active', 'https://sta.uwi.edu/HEALTH/about', '2026-10-22', 14) on conflict (id) do update set name = excluded.name, provider = excluded.provider, category = excluded.category, summary = excluded.summary, eligibility = excluded.eligibility, how_to_verify = excluded.how_to_verify, url = excluded.url, countries = excluded.countries, university_ids = excluded.university_ids, status = excluded.status, source_url = excluded.source_url, last_verified = excluded.last_verified, sort_order = excluded.sort_order;
