insert into public.perk_programs (id, kind, name, provider, countries, summary, how_to, url, merchants, window_days, interests, issuers, student_only, status, source_url, last_verified, sort_order) values ('hilton_honors', 'loyalty', 'Hilton Honors', 'Hilton', array[]::text[], 'Points expire after 24 months with no qualifying activity (a stay, card earning, a partner, or buying or donating points).', 'Do one qualifying activity every 24 months.', 'https://www.hilton.com/en/p/hilton-honors/ways-to-stay-active/', array['hilton']::text[], null, array['travel']::text[], array[]::text[], false, 'active', 'https://www.hilton.com/en/hilton-honors/support-faq/', '2026-10-22', 2) on conflict (id) do update set kind = excluded.kind, name = excluded.name, provider = excluded.provider, countries = excluded.countries, summary = excluded.summary, how_to = excluded.how_to, url = excluded.url, merchants = excluded.merchants, window_days = excluded.window_days, interests = excluded.interests, issuers = excluded.issuers, student_only = excluded.student_only, status = excluded.status, source_url = excluded.source_url, last_verified = excluded.last_verified, sort_order = excluded.sort_order;
