insert into public.perk_programs (id, kind, name, provider, countries, summary, how_to, url, merchants, window_days, interests, issuers, student_only, status, source_url, last_verified, sort_order) values ('massy_card', 'loyalty', 'Massy Card', 'Massy', array['TT']::text[], 'Points at Massy Stores and partners (1 point per TT$10 at launch). We couldn''t confirm if or when points expire.', 'Check your balance in the Massy Card app or on your receipt, and add it here with any expiry date.', 'https://massygroup.com/news-item/welcome-to-the-massy-card-welcome-to-more-rewards/', array['massy']::text[], null, array['groceries']::text[], array[]::text[], false, 'TODO_VERIFY', 'https://massygroup.com/news-item/welcome-to-the-massy-card-welcome-to-more-rewards/', null, 5) on conflict (id) do update set kind = excluded.kind, name = excluded.name, provider = excluded.provider, countries = excluded.countries, summary = excluded.summary, how_to = excluded.how_to, url = excluded.url, merchants = excluded.merchants, window_days = excluded.window_days, interests = excluded.interests, issuers = excluded.issuers, student_only = excluded.student_only, status = excluded.status, source_url = excluded.source_url, last_verified = excluded.last_verified, sort_order = excluded.sort_order;
insert into public.perk_programs (id, kind, name, provider, countries, summary, how_to, url, merchants, window_days, interests, issuers, student_only, status, source_url, last_verified, sort_order) values ('target_price_match', 'price_adjust', 'Target price match', 'Target', array['US']::text[], 'If Target lowers the price of an identical item within 14 days of your purchase, it refunds the difference. Clearance is excluded.', 'Bring the receipt to a store, or call 1-800-591-3869 for Target.com orders. Screenshots aren''t accepted — show the live price.', 'https://www.target.com/help/articles/policies-guidelines/price-match-guarantee', array['target']::text[], 14, array[]::text[], array[]::text[], false, 'active', 'https://www.target.com/help/articles/policies-guidelines/price-match-guarantee', '2026-10-22', 6) on conflict (id) do update set kind = excluded.kind, name = excluded.name, provider = excluded.provider, countries = excluded.countries, summary = excluded.summary, how_to = excluded.how_to, url = excluded.url, merchants = excluded.merchants, window_days = excluded.window_days, interests = excluded.interests, issuers = excluded.issuers, student_only = excluded.student_only, status = excluded.status, source_url = excluded.source_url, last_verified = excluded.last_verified, sort_order = excluded.sort_order;
insert into public.perk_programs (id, kind, name, provider, countries, summary, how_to, url, merchants, window_days, interests, issuers, student_only, status, source_url, last_verified, sort_order) values ('best_buy_price_match', 'price_adjust', 'Best Buy price match', 'Best Buy', array['US']::text[], 'If Best Buy lowers its price during your return and exchange period, it matches the lower price on request — more than once. Open-box and clearance are excluded.', 'Online orders: chat or call 1-888-237-8289. Store purchases: Customer Service desk.', 'https://www.bestbuy.com/site/help-topics/price-match-guarantee/pcmcat290300050002.c?id=pcmcat290300050002', array['best buy', 'bestbuy']::text[], null, array[]::text[], array[]::text[], false, 'active', 'https://www.bestbuy.com/site/help-topics/price-match-guarantee/pcmcat290300050002.c?id=pcmcat290300050002', '2026-10-22', 7) on conflict (id) do update set kind = excluded.kind, name = excluded.name, provider = excluded.provider, countries = excluded.countries, summary = excluded.summary, how_to = excluded.how_to, url = excluded.url, merchants = excluded.merchants, window_days = excluded.window_days, interests = excluded.interests, issuers = excluded.issuers, student_only = excluded.student_only, status = excluded.status, source_url = excluded.source_url, last_verified = excluded.last_verified, sort_order = excluded.sort_order;
insert into public.perk_programs (id, kind, name, provider, countries, summary, how_to, url, merchants, window_days, interests, issuers, student_only, status, source_url, last_verified, sort_order) values ('costco_price_adjustment', 'price_adjust', 'Costco price adjustment', 'Costco', array['US']::text[], 'If the price drops within 30 days of purchase, members can get the difference back. Costco can deny requests at its discretion.', 'Costco.com orders: the price adjustment form online. Warehouse purchases: the returns counter where you bought it.', 'https://customerservice.costco.com/app/answers/answer_view/a_id/628/~/price-match---costco.com-orders', array['costco']::text[], 30, array[]::text[], array[]::text[], false, 'active', 'https://customerservice.costco.com/app/answers/answer_view/a_id/628/~/price-match---costco.com-orders', '2026-10-22', 8) on conflict (id) do update set kind = excluded.kind, name = excluded.name, provider = excluded.provider, countries = excluded.countries, summary = excluded.summary, how_to = excluded.how_to, url = excluded.url, merchants = excluded.merchants, window_days = excluded.window_days, interests = excluded.interests, issuers = excluded.issuers, student_only = excluded.student_only, status = excluded.status, source_url = excluded.source_url, last_verified = excluded.last_verified, sort_order = excluded.sort_order;
insert into public.perk_programs (id, kind, name, provider, countries, summary, how_to, url, merchants, window_days, interests, issuers, student_only, status, source_url, last_verified, sort_order) values ('macys_price_adjustment', 'price_adjust', 'Macy''s price adjustment', 'Macy''s', array['US']::text[], 'If an eligible item''s advertised price drops within 10 days of your order, Macy''s refunds the difference. Clearance and some items are excluded.', 'Request it from Macy''s customer service; it goes back to your original payment method.', 'https://www.macys.com/customer-service/articles/how-can-i-get-a-price-adjustment', array['macy''s', 'macys']::text[], 10, array[]::text[], array[]::text[], false, 'active', 'https://www.macys.com/customer-service/articles/how-can-i-get-a-price-adjustment', '2026-10-22', 9) on conflict (id) do update set kind = excluded.kind, name = excluded.name, provider = excluded.provider, countries = excluded.countries, summary = excluded.summary, how_to = excluded.how_to, url = excluded.url, merchants = excluded.merchants, window_days = excluded.window_days, interests = excluded.interests, issuers = excluded.issuers, student_only = excluded.student_only, status = excluded.status, source_url = excluded.source_url, last_verified = excluded.last_verified, sort_order = excluded.sort_order;
insert into public.perk_programs (id, kind, name, provider, countries, summary, how_to, url, merchants, window_days, interests, issuers, student_only, status, source_url, last_verified, sort_order) values ('us_missing_money', 'unclaimed', 'Unclaimed money (US states)', 'NAUPA · MissingMoney.com', array['US']::text[], 'Forgotten bank balances, refunds, deposits and insurance payouts held by states. Searching is free.', 'Search your name on MissingMoney.com, plus your state''s own site. Never pay a finder to search.', 'https://www.missingmoney.com/', array[]::text[], null, array[]::text[], array[]::text[], false, 'active', 'https://unclaimed.org/search-for-your-unclaimed-property-its-free/', '2026-10-22', 10) on conflict (id) do update set kind = excluded.kind, name = excluded.name, provider = excluded.provider, countries = excluded.countries, summary = excluded.summary, how_to = excluded.how_to, url = excluded.url, merchants = excluded.merchants, window_days = excluded.window_days, interests = excluded.interests, issuers = excluded.issuers, student_only = excluded.student_only, status = excluded.status, source_url = excluded.source_url, last_verified = excluded.last_verified, sort_order = excluded.sort_order;
insert into public.perk_programs (id, kind, name, provider, countries, summary, how_to, url, merchants, window_days, interests, issuers, student_only, status, source_url, last_verified, sort_order) values ('tt_unclaimed_securities', 'unclaimed', 'Unclaimed government bond payments', 'Central Bank of Trinidad and Tobago', array['TT']::text[], 'Unpaid interest and maturity payments on government bonds, treasury bills and notes. The Central Bank publishes the names.', 'Check the list, then call the Government Services Unit at 621-2288 or 235-2288.', 'https://www.central-bank.org.tt/notice-collection-unclaimed-funds', array[]::text[], null, array[]::text[], array[]::text[], false, 'active', 'https://www.central-bank.org.tt/notice-collection-unclaimed-funds', '2026-10-22', 11) on conflict (id) do update set kind = excluded.kind, name = excluded.name, provider = excluded.provider, countries = excluded.countries, summary = excluded.summary, how_to = excluded.how_to, url = excluded.url, merchants = excluded.merchants, window_days = excluded.window_days, interests = excluded.interests, issuers = excluded.issuers, student_only = excluded.student_only, status = excluded.status, source_url = excluded.source_url, last_verified = excluded.last_verified, sort_order = excluded.sort_order;
insert into public.perk_programs (id, kind, name, provider, countries, summary, how_to, url, merchants, window_days, interests, issuers, student_only, status, source_url, last_verified, sort_order) values ('jm_unclaimed_balances', 'unclaimed', 'Unclaimed bank balances', 'Ministry of Finance and the Public Service', array['JM']::text[], 'Accounts untouched for 15+ years are published twice a year. Claim at your bank within a year of publication, then from the Accountant General.', 'Search the latest list on the Ministry''s publications page, then contact the bank named.', 'https://www.mof.gov.jm/documents/publications/', array[]::text[], null, array[]::text[], array[]::text[], false, 'active', 'https://mof.gov.jm/about/overview/faq/183-financial-regulations/22-how-can-i-obtain-my-money-published-as-unclaimed-balances-in-the-newspaper.html', '2026-10-22', 12) on conflict (id) do update set kind = excluded.kind, name = excluded.name, provider = excluded.provider, countries = excluded.countries, summary = excluded.summary, how_to = excluded.how_to, url = excluded.url, merchants = excluded.merchants, window_days = excluded.window_days, interests = excluded.interests, issuers = excluded.issuers, student_only = excluded.student_only, status = excluded.status, source_url = excluded.source_url, last_verified = excluded.last_verified, sort_order = excluded.sort_order;
insert into public.perk_programs (id, kind, name, provider, countries, summary, how_to, url, merchants, window_days, interests, issuers, student_only, status, source_url, last_verified, sort_order) values ('bs_dormant_accounts', 'unclaimed', 'Dormant bank balances', 'Central Bank of The Bahamas', array['BS']::text[], 'Balances inactive for years are moved to the Central Bank for safekeeping until the owner claims them.', 'Ask the bank where you held the account — it makes the claim with the Central Bank for you.', 'https://www.centralbankbahamas.com/viewPDF/documents/2019-06-21-04-11-47-Dormant-Account-Guidelines.pdf', array[]::text[], null, array[]::text[], array[]::text[], false, 'active', 'https://www.centralbankbahamas.com/viewPDF/documents/2019-06-21-04-11-47-Dormant-Account-Guidelines.pdf', '2026-10-22', 13) on conflict (id) do update set kind = excluded.kind, name = excluded.name, provider = excluded.provider, countries = excluded.countries, summary = excluded.summary, how_to = excluded.how_to, url = excluded.url, merchants = excluded.merchants, window_days = excluded.window_days, interests = excluded.interests, issuers = excluded.issuers, student_only = excluded.student_only, status = excluded.status, source_url = excluded.source_url, last_verified = excluded.last_verified, sort_order = excluded.sort_order;
insert into public.perk_programs (id, kind, name, provider, countries, summary, how_to, url, merchants, window_days, interests, issuers, student_only, status, source_url, last_verified, sort_order) values ('bb_inactive_accounts', 'unclaimed', 'Inactive bank accounts', 'Barbados banks', array['BB']::text[], 'Banks publish lists of long-inactive accounts before unclaimed money goes to the Central Bank of Barbados. We couldn''t find an official searchable list.', 'Ask any bank where you''ve had an account whether you''re on its inactive-accounts list.', 'https://www.centralbank.org.bb/', array[]::text[], null, array[]::text[], array[]::text[], false, 'TODO_VERIFY', null, null, 14) on conflict (id) do update set kind = excluded.kind, name = excluded.name, provider = excluded.provider, countries = excluded.countries, summary = excluded.summary, how_to = excluded.how_to, url = excluded.url, merchants = excluded.merchants, window_days = excluded.window_days, interests = excluded.interests, issuers = excluded.issuers, student_only = excluded.student_only, status = excluded.status, source_url = excluded.source_url, last_verified = excluded.last_verified, sort_order = excluded.sort_order;
