insert into public.perk_programs (id, kind, name, provider, countries, summary, how_to, url, merchants, window_days, interests, issuers, student_only, status, source_url, last_verified, sort_order) values ('nalis', 'library', 'NALIS library card', 'NALIS', array['TT']::text[], 'Free for residents: e-books and audiobooks on Libby, popular magazines on Flipster and EBSCO research databases.', 'Register online, collect your card at a branch, then set your PIN for the digital library.', 'https://www.nalis.gov.tt/FAQs', array[]::text[], null, array[]::text[], array[]::text[], false, 'active', 'https://www.nalis.gov.tt/FAQs', '2026-10-22', 17) on conflict (id) do update set kind = excluded.kind, name = excluded.name, provider = excluded.provider, countries = excluded.countries, summary = excluded.summary, how_to = excluded.how_to, url = excluded.url, merchants = excluded.merchants, window_days = excluded.window_days, interests = excluded.interests, issuers = excluded.issuers, student_only = excluded.student_only, status = excluded.status, source_url = excluded.source_url, last_verified = excluded.last_verified, sort_order = excluded.sort_order;
