insert into public.perk_programs (id, kind, name, provider, countries, summary, how_to, url, merchants, window_days, interests, issuers, student_only, status, source_url, last_verified, sort_order) values ('us_dot_flight_refunds', 'refund_rule', 'Cancelled or very late US flights', 'US Department of Transportation', array[]::text[], 'Flights to, from or within the US: if it''s cancelled or delayed 3+ hours (domestic) or 6+ hours (international) and you don''t accept another option, you''re owed a cash refund — within 7 business days for card payments.', 'Decline the rebooking or credit if you want the money back. If it doesn''t arrive, file a complaint with the DOT.', 'https://www.transportation.gov/individuals/aviation-consumer-protection/refunds', array[]::text[], null, array[]::text[], array[]::text[], false, 'active', 'https://www.transportation.gov/individuals/aviation-consumer-protection/refunds', '2026-10-22', 19) on conflict (id) do update set kind = excluded.kind, name = excluded.name, provider = excluded.provider, countries = excluded.countries, summary = excluded.summary, how_to = excluded.how_to, url = excluded.url, merchants = excluded.merchants, window_days = excluded.window_days, interests = excluded.interests, issuers = excluded.issuers, student_only = excluded.student_only, status = excluded.status, source_url = excluded.source_url, last_verified = excluded.last_verified, sort_order = excluded.sort_order;
insert into public.perk_programs (id, kind, name, provider, countries, summary, how_to, url, merchants, window_days, interests, issuers, student_only, status, source_url, last_verified, sort_order) values ('eu261', 'refund_rule', 'Delayed or cancelled flights in Europe', 'European Union', array[]::text[], 'Flights leaving the EU, or into the EU on an EU airline: €250–€600 compensation when you arrive 3+ hours late or a late cancellation, unless the airline proves extraordinary circumstances.', 'Claim from the airline first; each EU country has a body that handles complaints.', 'https://europa.eu/youreurope/citizens/travel/passenger-rights/air/index_en.htm', array[]::text[], null, array[]::text[], array[]::text[], false, 'active', 'https://eur-lex.europa.eu/eli/reg/2004/261/oj/eng', '2026-10-22', 20) on conflict (id) do update set kind = excluded.kind, name = excluded.name, provider = excluded.provider, countries = excluded.countries, summary = excluded.summary, how_to = excluded.how_to, url = excluded.url, merchants = excluded.merchants, window_days = excluded.window_days, interests = excluded.interests, issuers = excluded.issuers, student_only = excluded.student_only, status = excluded.status, source_url = excluded.source_url, last_verified = excluded.last_verified, sort_order = excluded.sort_order;
insert into public.perk_programs (id, kind, name, provider, countries, summary, how_to, url, merchants, window_days, interests, issuers, student_only, status, source_url, last_verified, sort_order) values ('us_billing_errors', 'refund_rule', 'Charged twice or for something you never got', 'Consumer Financial Protection Bureau', array['US']::text[], 'US credit cards: dispute billing errors in writing within 60 days of the statement that first shows them. You don''t have to pay the disputed amount while it''s investigated.', 'Call your card issuer, then send a letter to its billing-inquiries address.', 'https://www.consumerfinance.gov/consumer-tools/credit-cards/how-to-fix-mistakes-in-your-credit-card-bill/', array[]::text[], null, array[]::text[], array[]::text[], false, 'active', 'https://www.consumerfinance.gov/rules-policy/regulations/1026/13/', '2026-10-22', 21) on conflict (id) do update set kind = excluded.kind, name = excluded.name, provider = excluded.provider, countries = excluded.countries, summary = excluded.summary, how_to = excluded.how_to, url = excluded.url, merchants = excluded.merchants, window_days = excluded.window_days, interests = excluded.interests, issuers = excluded.issuers, student_only = excluded.student_only, status = excluded.status, source_url = excluded.source_url, last_verified = excluded.last_verified, sort_order = excluded.sort_order;
insert into public.perk_programs (id, kind, name, provider, countries, summary, how_to, url, merchants, window_days, interests, issuers, student_only, status, source_url, last_verified, sort_order) values ('us_health_fsa', 'deadline_rule', 'Health FSA: use it or lose it', 'IRS', array['US']::text[], 'Money left in a health FSA at the end of the plan year is lost, unless your plan has a grace period (up to 2½ months) or a carryover (up to $680 for 2026) — never both.', 'Check your plan''s deadline and add your balance here so PerkScan reminds you.', 'https://www.irs.gov/publications/p969', array[]::text[], null, array[]::text[], array[]::text[], false, 'active', 'https://www.irs.gov/pub/irs-pdf/iw2w3.pdf', '2026-10-22', 22) on conflict (id) do update set kind = excluded.kind, name = excluded.name, provider = excluded.provider, countries = excluded.countries, summary = excluded.summary, how_to = excluded.how_to, url = excluded.url, merchants = excluded.merchants, window_days = excluded.window_days, interests = excluded.interests, issuers = excluded.issuers, student_only = excluded.student_only, status = excluded.status, source_url = excluded.source_url, last_verified = excluded.last_verified, sort_order = excluded.sort_order;
